  def solid_icon(name, **options)
    options[:class] ||= "size-5"
    tag.svg(xmlns: "http://www.w3.org/2000/svg", fill: "currentColor", viewBox: "0 0 20 20", "aria-hidden": "true", **options) do
      tag.path("fill-rule": "evenodd", "clip-rule": "evenodd", d: SOLID_ICONS.fetch(name))
    end
  end

  def icon(name, **options)
    options[:class] ||= "size-5"
    tag.svg(xmlns: "http://www.w3.org/2000/svg", fill: "none", viewBox: "0 0 24 24", "stroke-width": "1.5", stroke: "currentColor", "aria-hidden": "true", **options) do
      tag.path("stroke-linecap": "round", "stroke-linejoin": "round", d: ICONS.fetch(name))
    end
  end
